 @BeforeAll void seed()throws Exception{var ids=List.of(owner,customer,stranger,printer);var roles=List.of("OWNER","CUSTOMER","CUSTOMER","OPERATOR");for(int n=0;n<ids.size();n++)jdbc.update("insert into staff_users(id,username,password_hash,role) values(?,?,?,?)",ids.get(n),"it-workflow-"+ids.get(n)+"@example.test",passwords.encode(password),roles.get(n));String seed=Totp.secret();jdbc.update("update staff_users set totp_secret=? where id=?",secrets.encrypt(seed),owner);boss=login(owner);assertEquals(200,boss.send("POST","/api/v1/auth/mfa/verify",json.writeValueAsString(Map.of("code",Totp.code(seed,Instant.now().getEpochSecond()/30))),true).statusCode());buyer=login(customer);other=login(stranger);press=login(printer);}
