 UUID lead(String email,UUID user){UUID id=UUID.randomUUID();leads.add(id);jdbc.update("insert into enquiries(id,public_id,tracking_token_sha256,customer_name,email,phone,product_code,quantity,status,assigned_staff_id,customer_user_id) values(?,?,?,'Synthetic workflow customer',?,'9000000000','WEDDING_CARDS',250,'REVIEWING',?,?)",id,UUID.randomUUID(),"0".repeat(64),email,owner,user);return id;}
 @AfterAll void clean()throws Exception{for(UUID id:extraAccounts){jdbc.update("update staff_users set enabled=false where id=?",id);jdbc.update("update mail_outbox set state='HELD',payload=null where user_id=?",id);}for(UUID id:List.of(owner,customer,stranger,printer))jdbc.update("update staff_users set enabled=false where id=?",id);for(UUID lead:leads){jdbc.update("update staff_users set enabled=false where id in (select customer_user_id from enquiries where id=?)",lead);jdbc.update("update mail_outbox set state='HELD',payload=null where enquiry_id=?",lead);}for(UUID file:files)store.discard(file);}
 @Test void projectMailSeparatesPhasesAndRecipientsAndKeepsRepliesWithinEachPhase(){
  UUID lead=lead("phase-customer@example.test",customer);String ref=UUID.randomUUID().toString();
  mail.queueProject(customer,lead,"phase-customer@example.test",ref,"ENQUIRY",lead,"Received");
  mail.queueProject(null,lead,"phase-owner@example.test",ref,"NEW_ENQUIRY",UUID.randomUUID(),"New enquiry");
  mail.queueProject(customer,lead,"phase-customer@example.test",ref,"INTAKE",UUID.randomUUID(),"Accepted");
  UUID quote=UUID.randomUUID();mail.queueProject(customer,lead,"phase-customer@example.test",ref,"REVIEW",quote,"Proof ready");
  mail.queueProject(null,lead,"phase-owner@example.test",ref,"REVIEW",UUID.randomUUID(),"Review ready");
  mail.queueProject(customer,lead,"phase-customer@example.test",ref,"DELIVERED",UUID.randomUUID(),"Delivered");
  var intake=jdbc.queryForMap("select message_id,reply_to_id,thread_root_id,subject from mail_outbox where enquiry_id=? and kind='ENQUIRY'",lead);
  var accepted=jdbc.queryForMap("select reply_to_id,thread_root_id,subject from mail_outbox where enquiry_id=? and kind='INTAKE'",lead);
  assertNull(intake.get("reply_to_id"));assertEquals(intake.get("message_id"),accepted.get("reply_to_id"));assertEquals(intake.get("subject"),accepted.get("subject"));
  var work=jdbc.queryForMap("select message_id,reply_to_id,thread_root_id,subject from mail_outbox where enquiry_id=? and kind='REVIEW' and recipient='phase-customer@example.test'",lead);
  assertNull(work.get("reply_to_id"));assertEquals(work.get("message_id"),work.get("thread_root_id"));assertNotEquals(intake.get("subject"),work.get("subject"));
  var delivered=jdbc.queryForMap("select reply_to_id,thread_root_id,subject from mail_outbox where enquiry_id=? and kind='DELIVERED'",lead);
  assertEquals(work.get("message_id"),delivered.get("reply_to_id"));assertEquals(work.get("thread_root_id"),delivered.get("thread_root_id"));assertEquals(work.get("subject"),delivered.get("subject"));
  mail.queueProject(customer,lead,"phase-customer@example.test",ref,"REVIEW",quote,"Retry");assertEquals(1,jdbc.queryForObject("select count(*) from mail_outbox where enquiry_id=? and recipient='phase-customer@example.test' and kind='REVIEW'",Integer.class,lead));
 }
